function HomepageCuration() {
  const [data,setData]=useState(null); const [form,setForm]=useState(null); const [error,setError]=useState(''); const [busy,setBusy]=useState(false);
  const load=async()=>{try{const result=await apiV3('/admin/catalogue/homepage');setData(result);setForm(result.config);}catch(e){setError(e.message);}};
  useEffect(()=>{load();},[]);
  const toggle=(key,id)=>setForm(current=>({...current,[key]:(current[key]||[]).includes(id)?current[key].filter(value=>value!==id):[...(current[key]||[]),id]}));
  const save=async event=>{event.preventDefault();setBusy(true);try{const result=await apiV3('/admin/catalogue/homepage',{method:'PATCH',body:JSON.stringify(form)});setForm(result.config);await load();}catch(e){setError(e.message);}finally{setBusy(false);}};
  if(!form)return <section className="homepage-curation"><span className="eyebrow">PUBLIC HOMEPAGE</span><p>{error||'Loading homepage curation…'}</p></section>;
  const choices=(title,key,records,label)=> <fieldset><legend>{title}</legend><div className="homepage-choice-list">{records.map(item=><label key={item.id}><input type="checkbox" checked={(form[key]||[]).includes(item.id)} onChange={()=>toggle(key,item.id)}/><span>{label(item)}</span></label>)}</div></fieldset>;
  return <section className="homepage-curation"><div className="catalogue-head"><div><span className="eyebrow">PUBLIC HOMEPAGE</span><h2>Curate the front page.</h2><p>Only records that are public at read time can appear. Invalid or missing choices fall back safely.</p></div><a className="report-button" href="/v3/" target="_blank" rel="noreferrer">Preview homepage ↗</a></div>{error&&<p className="error">{error}</p>}<form onSubmit={save} className="homepage-form"><div className="homepage-copy"><label>Hero eyebrow<input value={form.hero_eyebrow||''} maxLength="80" onChange={e=>setForm({...form,hero_eyebrow:e.target.value})}/></label><label>Hero title<input value={form.hero_title||''} maxLength="120" onChange={e=>setForm({...form,hero_title:e.target.value})}/></label><label>Hero summary<textarea value={form.hero_summary||''} maxLength="360" onChange={e=>setForm({...form,hero_summary:e.target.value})}/></label><div className="homepage-field"><span>Hero CTA</span><div><input aria-label="Hero CTA label" value={form.hero_cta_label||''} maxLength="48" onChange={e=>setForm({...form,hero_cta_label:e.target.value})}/><select aria-label="Hero CTA target" value={form.hero_cta_target||'/v3/videos'} onChange={e=>setForm({...form,hero_cta_target:e.target.value})}><option value="/v3/videos">Videos</option><option value="/v3/performers">Performers</option><option value="/v3/collections">Collections</option></select></div></div><label>Hero video<select value={form.hero_video_legacy_id||''} onChange={e=>setForm({...form,hero_video_legacy_id:e.target.value||null})}><option value="">Automatic fallback</option>{data?.candidates?.videos?.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></label><label>Hero performer<select value={form.hero_performer_legacy_id||''} onChange={e=>setForm({...form,hero_performer_legacy_id:e.target.value||null})}><option value="">Automatic fallback</option>{data?.candidates?.performers?.map(item=><option value={item.id} key={item.id}>{item.display_name}</option>)}</select></label><label>Hero collection<select value={form.hero_collection_id||''} onChange={e=>setForm({...form,hero_collection_id:e.target.value||null})}><option value="">Automatic fallback</option>{data?.candidates?.collections?.map(item=><option value={item.id} key={item.id}>{item.title}</option>)}</select></label></div><div className="homepage-sections"><fieldset><legend>Visible sections</legend>{Object.entries(form.section_visibility||{}).map(([key,value])=><label key={key}><input type="checkbox" checked={Boolean(value)} onChange={e=>setForm({...form,section_visibility:{...form.section_visibility,[key]:e.target.checked}})}/>{key.replaceAll('_',' ')}</label>)}</fieldset>{choices('Featured videos','featured_video_ids',data?.candidates?.videos||[],item=>item.title)}{choices('Featured performers','featured_performer_ids',data?.candidates?.performers||[],item=>item.display_name)}{choices('Featured collections','featured_collection_ids',data?.candidates?.collections||[],item=>item.title)}</div><button className="save" disabled={busy}>{busy?'Saving…':'Save audited homepage curation'}</button></form></section>;
}
function Catalogue({ section }) {
  const [kind,setKind]=useState('videos'); const [data,setData]=useState({records:[]}); const [q,setQ]=useState(''); const [page,setPage]=useState(1); const [filters,setFilters]=useState({lifecycle:'',status:'',missing_media:'',brand:'',performer:'',collection:''}); const [detail,setDetail]=useState(null); const [collections,setCollections]=useState([]); const [error,setError]=useState('');
  const load=async()=>{try{if(kind==='collections'){setCollections((await apiV3('/admin/catalogue/collections')).records||[]);return;}const params=new URLSearchParams({limit:'24',page:String(page),q,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v))});setData(await apiV3(`/admin/catalogue/${kind}?${params}`));}catch(e){setError(e.message);}};
  useEffect(()=>{if(section==='Catalogue')load();},[section,kind,filters]); if(section!=='Catalogue')return null;
  const singular=kind==='videos'?'video':kind==='brands'?'brand':'performer'; const open=async row=>{try{setDetail(await apiV3(`/admin/catalogue/${singular}/${row.legacy_id}`));}catch(e){setError(e.message);}};
  const change=(field,value)=>setDetail({...detail,record:{...detail.record,[field]:value}});
  const save=async()=>{try{const r=detail.record;await apiV3(`/admin/catalogue/${singular}/${r.legacy_id}`,{method:'PATCH',body:JSON.stringify({...r,seo_title:r.seo_title,seo_description:r.seo_description,internal_publishing_notes:r.internal_publishing_notes})});await open(r);await load();}catch(e){setError(e.message);}};
  const transition=async action=>{try{await apiV3(`/admin/catalogue/video/${detail.record.legacy_id}/${action}`,{method:'POST',body:'{}'});await open(detail.record);await load();}catch(e){setError(e.message);}};
  const assignMedia=async()=>{try{await apiV3(`/admin/catalogue/video/${detail.record.legacy_id}/media`,{method:'PUT',body:JSON.stringify({asset_id:detail.mediaAssetId,asset_type:detail.mediaAssetType||'thumbnail'})});await open(detail.record);}catch(e){setError(e.message);}};
  const rows=kind==='collections'?collections:data.records||[];
  return <section className="catalogue"><div className="catalogue-head"><div><span className="eyebrow">CATALOGUE OPERATIONS</span><h2>Live library.</h2><p>Server-validated metadata, media and publishing controls.</p></div><div><p>{kind==='collections'?collections.length:data.total||0} records</p></div></div><div className="tabs">{['videos','performers','brands','collections'].map(tab=><button className={kind===tab?'active':''} key={tab} onClick={()=>{setKind(tab);setPage(1);setDetail(null);}}>{tab}</button>)}</div>{kind!=='collections'&&<div className="catalogue-filters"><input className="search" value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){setPage(1);load();}}} placeholder={`Search ${kind}`}/>{kind==='videos'&&<><select value={filters.lifecycle} onChange={e=>setFilters({...filters,lifecycle:e.target.value})}><option value="">All lifecycle</option>{['draft','metadata_ready','media_ready','qa_review','certification_review','publishable','published','archived'].map(v=><option key={v}>{v}</option>)}</select><select value={filters.status} onChange={e=>setFilters({...filters,status:e.target.value})}><option value="">All status</option>{['draft','published','unlisted','archived'].map(v=><option key={v}>{v}</option>)}</select><input placeholder="Brand ID" value={filters.brand} onChange={e=>setFilters({...filters,brand:e.target.value})}/><input placeholder="Performer ID" value={filters.performer} onChange={e=>setFilters({...filters,performer:e.target.value})}/><input placeholder="Collection ID" value={filters.collection} onChange={e=>setFilters({...filters,collection:e.target.value})}/><label><input type="checkbox" checked={filters.missing_media==='true'} onChange={e=>setFilters({...filters,missing_media:e.target.checked?'true':''})}/> missing media</label></>}</div>}{error&&<p className="error">{error}</p>}<div className="catalogue-grid">{rows.map(row=><button className="record" key={row.id||row.legacy_id} onClick={()=>kind==='collections'?null:open(row)}>{row.legacy_thumbnail_url?<img src={row.legacy_thumbnail_url} alt=""/>:<div className="poster"/>}<span>{row.v3_lifecycle||row.visibility||row.status}</span><h3>{row.title||row.display_name||row.name}</h3><small>{row.performer_names?.join(' · ')|| (row.video_count!=null?`${row.video_count} videos`:row.slug)}</small></button>)}</div>{kind!=='collections'&&<div className="pagination"><button disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {page} of {data.pages||1}</span><button disabled={page>=(data.pages||1)} onClick={()=>setPage(page+1)}>Next</button></div>}{detail&&<aside className="detail"><button onClick={()=>setDetail(null)}>Close</button><span className="eyebrow">{singular.toUpperCase()} DETAIL</span><h2>{detail.record.title||detail.record.display_name||detail.record.name}</h2><label>Title / name<input value={detail.record.title||detail.record.display_name||detail.record.name||''} onChange={e=>change(kind==='videos'?'title':kind==='performers'?'display_name':'name',e.target.value)}/></label><label>Slug<input value={detail.record.slug||''} onChange={e=>change('slug',e.target.value)}/></label><label>Description<textarea value={detail.record.description||detail.record.bio||''} onChange={e=>change(kind==='performers'?'bio':'description',e.target.value)}/></label>{kind==='videos'&&<><label>Summary<textarea value={detail.record.short_summary||''} onChange={e=>change('short_summary',e.target.value)}/></label><label>Lifecycle<select value={detail.record.v3_lifecycle||'draft'} onChange={e=>change('v3_lifecycle',e.target.value)}>{['draft','metadata_ready','media_ready','qa_review','certification_review','publishable','published','archived'].map(v=><option key={v}>{v}</option>)}</select></label><label>SEO title<input value={detail.record.seo_title||''} onChange={e=>change('seo_title',e.target.value)}/></label><label>SEO description<textarea value={detail.record.seo_description||''} onChange={e=>change('seo_description',e.target.value)}/></label><label>Internal publishing notes<textarea value={detail.record.internal_publishing_notes||''} onChange={e=>change('internal_publishing_notes',e.target.value)}/></label><div className="readiness-panel"><b>{detail.publish?.publishable?'READY TO PUBLISH':'PUBLISH BLOCKED'}</b><ul>{(detail.publish?.blockers||[]).map(b=><li key={b}>{b}</li>)}</ul>{(detail.publish?.warnings||[]).map(w=><small key={w}>Warning: {w}</small>)}</div><p>Performers: {detail.record.performers?.map(x=>x.name).join(', ')||'none'}</p><p>Media: {(detail.media||[]).map(x=>`${x.asset_type}:${x.processing_state}/${x.visibility}${x.is_primary?' (primary)':''}`).join(' · ')||'none assigned'}</p><label>Assign ready public asset ID<input value={detail.mediaAssetId||''} onChange={e=>setDetail({...detail,mediaAssetId:e.target.value})}/></label><select value={detail.mediaAssetType||'thumbnail'} onChange={e=>setDetail({...detail,mediaAssetType:e.target.value})}><option>thumbnail</option><option>poster</option><option>trailer</option></select><button onClick={assignMedia}>Assign media</button><div className="button-row"><button className="save" onClick={()=>transition('publish')} disabled={!detail.publish?.publishable}>Publish</button><button onClick={()=>transition('unpublish')}>Unpublish</button><button onClick={()=>transition('archive')}>Archive</button></div></>}<button className="save" onClick={save}>Save metadata</button><pre>{JSON.stringify(detail.audit||[],null,2)}</pre></aside>}</section>;
}

function V3Entry() {
  const pathname = window.location.pathname;
  const adminRequested = new URLSearchParams(window.location.search).get('admin') === '1';
  const publicPath = pathname !== '/v3/' && pathname !== '/v3';
  const [mode, setMode] = useState(publicPath || adminRequested ? (adminRequested ? 'admin' : 'public') : 'checking');
  useEffect(() => {
    if (publicPath || adminRequested) return;
    fetch('/api/v1/auth/me', { credentials: 'include' }).then((response) => setMode(response.ok ? 'admin' : 'public')).catch(() => setMode('public'));
  }, [publicPath, adminRequested]);
  if (mode === 'checking') return <main className="public-empty" style={{ minHeight: '100vh' }}>Loading catalogue…</main>;
  return mode === 'admin' ? <App /> : <PublicApp />;
}
createRoot(document.getElementById('root')).render(<V3Entry/>);
